mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  vec3 q = p;
  q.xz = rot(q.y * 0.8 + time * 0.4) * q.xz;
  float spire = max(abs(q.x), abs(q.z)) - (0.45 - q.y * 0.16);
  spire = max(spire, abs(p.y) - 2.4);
  float ring = length(vec2(length(p.xz) - 1.4, p.y - sin(time * 2.0) * 0.6)) - 0.05;
  return min(spire, ring);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.6, -4.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 9.0) break;
    t += d * 0.75;
  }
  vec3 col = vec3(0.02, 0.01, 0.04);
  if (t < 9.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.003, 0.0);
    vec3 n = normalize(vec3(map(pos+e.xyy)-map(pos-e.xyy), map(pos+e.yxy)-map(pos-e.yxy), map(pos+e.yyx)-map(pos-e.yyx)));
    vec3 l = normalize(vec3(1.0, 2.0, -1.5));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 40.0);
    float rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
    vec3 irid = 0.5 + 0.5 * cos(vec3(0.0, 1.5, 3.0) + dot(n, -rd) * 5.0 + time);
    col = vec3(0.05, 0.02, 0.08) + diff * irid + spec * vec3(1.0, 0.9, 0.8) + rim * vec3(1.0, 0.3, 0.7);
  }
  col += glow * vec3(0.9, 0.4, 1.0) * (0.8 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
